#Requires -Version 7.2

# Runs scripts/size-check.ps1 on generated fixtures, one per case of the size-check table: the production
# and test caps and hard caps, the size: reason line and where it counts, generated files, CRLF and a
# missing final newline, a missing file. Fixtures are written under .temp/size-check-test/ on every run, so
# no large file is tracked. size-check-test.sh is the twin.

Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'

$ScriptName = 'size-check-test.ps1'

function Fail {
    param([Parameter(Mandatory = $true)][string]$Message)
    $Host.UI.WriteErrorLine("$ScriptName`: $Message")
    exit 1
}

function Show-Usage {
    @"
Usage: scripts/$ScriptName

Runs scripts/size-check.ps1 on generated fixtures and checks the exit code and messages of each case.

  -h, --help   Show this message.
"@
}

if ($args.Count -gt 0) {
    switch -CaseSensitive ($args[0]) {
        { $_ -cin '-h', '--help' } { Show-Usage; exit 0 }
        default { Fail "unknown argument: $($args[0])" }
    }
}

$RepoRoot = Split-Path -Parent $PSScriptRoot
Set-Location $RepoRoot

$WorkRel = '.temp/size-check-test'
$WorkAbs = Join-Path $RepoRoot $WorkRel
if (Test-Path -LiteralPath $WorkAbs) { Remove-Item -LiteralPath $WorkAbs -Recurse -Force }
New-Item -ItemType Directory -Force -Path $WorkAbs | Out-Null

function Get-Block {
    param([Parameter(Mandatory = $true)][string]$Block)
    switch ($Block) {
        'none' { @() }
        'one' { @('//! size: one long ported function') }
        'x' { @('//! size: x') }
        'upper' { @('//! Size: x') }
        'nodoc' { @('// size: table of cases', 'use x;') }
        'late' { @('use x;', '//! size: late') }
        'item' { @('//! Module.', '/// size: x', 'fn a() {}') }
        'empty' { @('//! size:') }
        'gen1' { @('// @generated by gen_x.py') }
        'gen2' { @('//! Module.', '// @generated') }
        'docmix' { @('//! The table helpers.', '// size: x') }
        'attr' { @('#![allow(', '    clippy::unwrap_used,', ')]', '//! size: helper') }
        default { Fail "unknown block: $Block" }
    }
}

# New-Fixture <rel path> <block> <total lines>: the same fixture the .sh twin writes.
function New-Fixture {
    param([string]$Rel, [string]$Block, [int]$Total)
    $Path = Join-Path $WorkAbs $Rel
    New-Item -ItemType Directory -Force -Path (Split-Path -Parent $Path) | Out-Null
    $Lines = [Collections.Generic.List[string]]::new()
    $Lines.AddRange([string[]]@(Get-Block $Block))
    while ($Lines.Count -lt $Total) { $Lines.Add('x') }
    [IO.File]::WriteAllText($Path, (($Lines -join "`n") + "`n"))
}

New-Fixture 'src/p800.rs' 'none' 800
New-Fixture 'src/p801.rs' 'none' 801
New-Fixture 'src/p801r.rs' 'one' 801
New-Fixture 'src/p1200r.rs' 'one' 1200
New-Fixture 'src/p1201r.rs' 'one' 1201
New-Fixture 'src/nodoc.rs' 'nodoc' 801
New-Fixture 'src/late.rs' 'late' 801
New-Fixture 'src/itemdoc.rs' 'item' 801
New-Fixture 'src/empty.rs' 'empty' 801
New-Fixture 'src/gen1.rs' 'gen1' 5000
New-Fixture 'src/gen2.rs' 'gen2' 5000
New-Fixture 'src/docmix.rs' 'docmix' 801
New-Fixture 'src/attr.rs' 'attr' 801
New-Fixture 'tests/t1000.rs' 'none' 1000
New-Fixture 'tests/t1001.rs' 'none' 1001
New-Fixture 'src/m/tests/a.rs' 'none' 1001
New-Fixture 'src/m/tests.rs' 'none' 1001
New-Fixture 'tests/t1501r.rs' 'x' 1501
New-Fixture 'src/upper.rs' 'upper' 801
New-Fixture 'src/Tests/a.rs' 'none' 801
[IO.File]::WriteAllText((Join-Path $WorkAbs 'src/crlf.rs'), ("//! size: crlf`r`n" + ('x' + "`r`n") * 800))
[IO.File]::WriteAllText((Join-Path $WorkAbs 'src/noeol.rs'), ('x' + "`n") * 800 + 'x')

$Passes = 0
$Failures = 0

# Invoke-Case <number> <expected exit> <expected stdout> <expected stderr lines, newline-separated, or empty>
# <files...>: runs size-check.ps1 in its own process and checks the exit code, the exact stdout and each
# stderr line.
function Invoke-Case {
    param([int]$Num, [int]$WantExit, [string]$WantOut, [string]$WantErr, [string[]]$Files)
    $TwinPath = Join-Path $RepoRoot 'scripts/size-check.ps1'
    $OutFile = Join-Path $WorkAbs "out-$Num"
    $ErrFile = Join-Path $WorkAbs "err-$Num"
    $Argv = @('-NoProfile', '-File', $TwinPath) + $Files
    $Proc = Start-Process -FilePath 'pwsh' -ArgumentList $Argv -NoNewWindow -Wait -PassThru `
        -RedirectStandardOutput $OutFile -RedirectStandardError $ErrFile
    $Got = [IO.File]::ReadAllText($OutFile).TrimEnd()
    $GotErr = [IO.File]::ReadAllText($ErrFile)
    $Problems = [Collections.Generic.List[string]]::new()
    if ($Proc.ExitCode -ne $WantExit) { $Problems.Add("exit $($Proc.ExitCode), want $WantExit") }
    if ($Got -cne $WantOut) { $Problems.Add("stdout '$Got', want '$WantOut'") }
    foreach ($Want in @($WantErr -split "`n" | Where-Object { $_ })) {
        if (-not $GotErr.Contains($Want)) { $Problems.Add("stderr lacks '$Want'") }
    }
    if ($Problems.Count -eq 0) {
        $script:Passes++
    } else {
        $Host.UI.WriteErrorLine("size-check-test.ps1: case $($Num): $($Problems -join '; ')")
        $script:Failures++
    }
}

$Ok1 = 'size-check: 1 files checked, 0 generated skipped'
$Prefix = $WorkRel

Invoke-Case 1 0 $Ok1 '' @("$Prefix/src/p800.rs")
Invoke-Case 2 1 '' "$Prefix/src/p801.rs: 801 lines, over the 800-line production cap without a size: line" @("$Prefix/src/p801.rs")
Invoke-Case 3 0 $Ok1 '' @("$Prefix/src/p801r.rs")
Invoke-Case 4 1 '' "$Prefix/src/p1201r.rs: 1201 lines, over the 1200-line production hard cap" @("$Prefix/src/p1201r.rs")
Invoke-Case 5 0 $Ok1 '' @("$Prefix/src/nodoc.rs")
Invoke-Case 6 1 '' "$Prefix/src/late.rs: 801 lines, over the 800-line production cap without a size: line" @("$Prefix/src/late.rs")
Invoke-Case 7 1 '' "$Prefix/src/itemdoc.rs: 801 lines, over the 800-line production cap without a size: line" @("$Prefix/src/itemdoc.rs")
Invoke-Case 8 1 '' "$Prefix/src/empty.rs: 801 lines, over the 800-line production cap without a size: line" @("$Prefix/src/empty.rs")
Invoke-Case 9 1 '' "$Prefix/src/gen2.rs: 5000 lines, over the 1200-line production hard cap" @("$Prefix/src/gen2.rs", "$Prefix/src/p800.rs")
Invoke-Case 10 0 'size-check: 1 files checked, 1 generated skipped' '' @("$Prefix/src/gen1.rs", "$Prefix/src/p800.rs")
Invoke-Case 11 1 '' ("$Prefix/tests/t1001.rs: 1001 lines, over the 1000-line test cap without a size: line`n" +
    "$Prefix/src/m/tests/a.rs: 1001 lines, over the 1000-line test cap without a size: line`n" +
    "$Prefix/src/m/tests.rs: 1001 lines, over the 1000-line test cap without a size: line") `
    @("$Prefix/tests/t1001.rs", "$Prefix/src/m/tests/a.rs", "$Prefix/src/m/tests.rs")
Invoke-Case 12 1 '' 'size-check.ps1: no hand-written .rs file checked' @("$Prefix/src/gen1.rs")
Invoke-Case 13 0 $Ok1 '' @("$Prefix/src/crlf.rs")
Invoke-Case 14 1 '' "$Prefix/src/noeol.rs: 801 lines, over the 800-line production cap without a size: line" @("$Prefix/src/noeol.rs")
Invoke-Case 15 0 $Ok1 '' @("$Prefix/src/attr.rs")
Invoke-Case 16 1 '' "$Prefix/src/nope.rs: no such file" @("$Prefix/src/nope.rs")
Invoke-Case 17 1 '' "$Prefix/src/docmix.rs: 801 lines, over the 800-line production cap without a size: line" @("$Prefix/src/docmix.rs")
Invoke-Case 18 0 $Ok1 '' @("$Prefix/src/p1200r.rs")
Invoke-Case 19 0 $Ok1 '' @("$Prefix/tests/t1000.rs")
Invoke-Case 20 1 '' "$Prefix/tests/t1501r.rs: 1501 lines, over the 1500-line test hard cap" @("$Prefix/tests/t1501r.rs")
Invoke-Case 21 1 '' "$Prefix/src/upper.rs: 801 lines, over the 800-line production cap without a size: line" @("$Prefix/src/upper.rs")
Invoke-Case 22 1 '' "$Prefix/src/Tests/a.rs: 801 lines, over the 800-line production cap without a size: line" @("$Prefix/src/Tests/a.rs")

if ($Failures -gt 0) { exit 1 }
"size-check-test: $Passes cases passed"
